css:
.skh-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #fff);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #000);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.skh-root,.skh-root *,.skh-root *::before,.skh-root *::after{box-sizing:border-box}
.skh-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.skh-root img{display:block;border:0;max-width:none}
.skh-root .n64_3900{background-color:var(--wa-bg, #fff);align-content:stretch;display:flex;gap:8px;height:30px;align-items:center;padding-left:8px;padding-right:8px;position:relative;border-radius:5px;flex-shrink:0;filter:drop-shadow(0px 3px 1.5px rgba(21,31,42,0.1))}
.skh-root .n64_3901{position:relative;flex-shrink:0;width:16px;height:16px}
.skh-root .x102{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.skh-root .n64_3903{height:30px;position:relative;flex-shrink:0;width:0}
.skh-root .x103{position:absolute;inset:0 -0.5px}
.skh-root .x104{display:block;max-width:none;width:100%;height:100%}
.skh-root .n64_3904{align-content:stretch;display:flex;height:30px;align-items:center;justify-content:center;padding-left:7px;padding-right:7px;position:relative;flex-shrink:0}
.skh-root .n64_3905{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:14px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #313131);font-size:12px;white-space:nowrap;width:33px}
.skh-root[data-theme="dark"] .n64_3900{background-color:var(--wa-point, #171b2c);filter:drop-shadow(0px 3px 1.5px rgba(0,0,0,0.45))}
.skh-root[data-theme="dark"] .n64_3905{color:var(--wa-text, #eceffa)}
.skh-root[data-theme="dark"] .n64_3903{opacity:.45}
.skh-root[data-theme="dark"] [id="skh-Needle"] svg [id$="-Vector"] path{fill:var(--wa-point, #242a44)}
.skh-root[data-theme="dark"] [id="skh-Needle"] svg [id$="-Vector_2"] path{fill:var(--wa-point, #dfe3f2)}
.skh-root[data-theme="dark"] [id="skh-Needle"] svg [id$="-Vector_3"]{stroke:var(--wa-point, #dfe3f2)}
.skh-root[data-theme="dark"] [id="skh-Needle"] img{filter:invert(.86) hue-rotate(180deg)}
.skh-root[data-theme="dark"] [id="skh-Radio"] svg rect:first-of-type{fill:var(--wa-point, #2a3050)}
